/* SportMatch — photos inlined as data URIs so exports (single-file
   artifacts, standalone HTML) carry their own imagery. SM_IMG builds photo
   paths as runtime strings, which static bundlers cannot discover; this patches
   SM_IMG.url to return the baked-in copy. Downscaled to 1200px / q82. */
(function () {
  var DATA = {"basketball-aerial":"data:image/jpeg;base64,","basketball-bw":"data:image/jpeg;base64,","football-match":"data:image/jpeg;base64,","football-sunset":"data:image/jpeg;base64,","streetball-bw":"data:image/jpeg;base64,","tennis-clay":"data:image/jpeg;base64,","tennis-net":"data:image/jpeg;base64,"};
  window.SM_PHOTO_DATA = DATA;
  function keyOf(s) { var m = String(s).match(/([^\/?#]+)\.jpg(?:[?#]|$)/); return m && m[1]; }
  function patch() {
    var img = window.SM_IMG;
    if (!img || img.__inlined) return !!img;
    var orig = img.url.bind(img);
    img.url = function (key) {
      if (DATA[key]) return DATA[key];
      var resolved = orig(key);
      var k = keyOf(resolved);
      return (k && DATA[k]) || resolved;
    };
    img.__inlined = true;
    return true;
  }
  if (!patch()) {
    var n = 0, iv = setInterval(function () { if (patch() || ++n > 200) clearInterval(iv); }, 20);
  }
  function sweep() {
    var imgs = document.querySelectorAll('img[src*="photos/"]');
    for (var i = 0; i < imgs.length; i++) {
      var k = keyOf(imgs[i].getAttribute('src') || '');
      if (k && DATA[k]) imgs[i].src = DATA[k];
    }
    var els = document.querySelectorAll('[style*="photos/"]');
    for (var j = 0; j < els.length; j++) {
      var k2 = keyOf(els[j].style.backgroundImage || '');
      if (k2 && DATA[k2]) els[j].style.backgroundImage = "url('" + DATA[k2] + "')";
    }
  }
  if (document.readyState !== 'loading') sweep();
  document.addEventListener('DOMContentLoaded', sweep);
  if (window.MutationObserver) {
    new MutationObserver(sweep).observe(document.documentElement,
      { childList: true, subtree: true, attributes: true, attributeFilter: ['src', 'style'] });
  }
})();
